# v4: ruling backfill 2023-2026 from entscheidsuche.ch (BGer, GE Cour de justice, NE Tribunal cantonal).
# Read from the decision texts; roles only, no names. Removes Téléverbier (victim was a skier).
# 'why' = one-paragraph court reasoning; defendant 'short' = one-line reason. verdict 'open' = sent back, outcome pending.
import json
P='/workspace/safetyradar/data/rulings.json'
def L(de,fr,it,en): return {"de":de,"fr":fr,"it":it,"en":en}
def S(units=None,amount=None,suspended=None,probation=None,fine=None,custodial=None,costs=None,compensation=None,other=None):
  return dict(dailyUnits=units,dailyAmount=amount,suspended=suspended,probationYears=probation,fineCHF=fine,custodial=custodial,costs=costs,compensation=compensation,bail=None,other=other)
def D(role,charge,verdict,reasoning,sanction,short=None): return dict(role=role,charge=charge,verdict=verdict,reasoning=reasoning,sanction=sanction,short=short or reasoning)
FKV=L("Fahrlässige schwere Körperverletzung","Lésions corporelles graves par négligence","Lesioni gravi colpose","Serious bodily harm by negligence")
FT=L("Fahrlässige Tötung","Homicide par négligence","Omicidio colposo","Negligent homicide")
R229=L("Fahrlässige Verletzung der Regeln der Baukunde","Violation par négligence des règles de l’art de construire","Violazione colposa delle regole dell’arte edilizia","Negligent breach of building rules")
FKV229=L("Fahrlässige schwere Körperverletzung und Verletzung der Regeln der Baukunde","Lésions corporelles graves par négligence et violation des règles de l’art de construire","Lesioni gravi colpose e violazione delle regole dell’arte edilizia","Serious bodily harm by negligence and breach of building rules")
V229=L("Vorsätzliche Gefährdung durch Verletzung der Regeln der Baukunde","Violation intentionnelle des règles de l’art de construire","Violazione intenzionale delle regole dell’arte edilizia","Intentional breach of building rules")
BGER=L("Bundesgericht","Tribunal fédéral","Tribunale federale","Federal Supreme Court")
GECJ=L("Cour de justice Genf, Strafkammer (Berufung)","Cour de justice de Genève, Chambre pénale d’appel et de révision","Cour de justice di Ginevra, Camera penale d’appello","Geneva Court of Justice, Criminal Appeals Chamber")
TFC=L("Bundesgerichtskosten CHF 3000","Frais du TF CHF 3000","Spese TF CHF 3000","Federal Court costs CHF 3,000")
CIVIL=L("Zivilforderungen auf den Zivilweg verwiesen","Prétentions civiles renvoyées au juge civil","Pretese civili rinviate al foro civile","Civil claims referred to the civil courts")
FATAL=L("Tödlich","Mortel","Mortale","Fatal")
def ES(u,l): return dict(name="entscheidsuche.ch",url=u,lang=l)
def R(id,date,accidentDate,canton,place,industry,hazard,outcome,court,case,final,appeal,employer,defendants,source,title,what,injuries,why,lesson,extra=None):
  return dict(id=id,caseId="case-"+id,date=date,accidentDate=accidentDate,canton=canton,place=place,industry=industry,hazard=hazard,outcome=outcome,
    court=court,caseNumber=case,final=final,appeal=appeal,employerRole=employer,defendants=defendants,linkedAccidentId=None,
    source=source,extraSources=extra or [],title=title,facts=dict(activity=None,what=what,injuries=injuries),why=why,lesson=lesson)
new=[]
new.append(R("2025-11-12-bger-6b-521-2025-fr-kran","2025-11-12","2018-09-26","FR",None,"industry","crane","fatal",BGER,"6B_521/2025",True,
 L("Erste Instanz sprach beide frei; das Kantonsgericht Freiburg verurteilte beide (2.4.2025); das Bundesgericht wies ihre Beschwerden ab – rechtskräftig.","Acquittés en première instance; condamnés par le Tribunal cantonal fribourgeois (2.4.2025); recours rejetés par le TF – définitif.","Assolti in prima istanza; condannati dal Tribunale cantonale friburghese (2.4.2025); ricorsi respinti dal TF – definitivo.","Both acquitted at first instance; convicted by the Fribourg Cantonal Court (2.4.2025); Federal Court dismissed their appeals – final."),
 L("Betrieb mit Werkhof; das Unternehmen war nicht angeklagt.","Entreprise avec dépôt; l’entreprise n’était pas prévenue.","Azienda con deposito; l’azienda non era imputata.","Company with a yard; the company itself was not charged."),
 [D(L("Sicherheitsbeauftragter","Chargé de sécurité","Incaricato della sicurezza","Safety officer"),FT,"convicted",
   L("Setzte von der Suva verlangte Massnahmen nicht um, schulte das Personal nicht und gab Sicherheitsinformationen nicht weiter.","N’a pas mis en œuvre les mesures exigées par la Suva, n’a pas formé le personnel ni transmis les informations de sécurité.","Non ha attuato le misure chieste dalla Suva, non ha formato il personale né trasmesso le informazioni di sicurezza.","Did not implement measures Suva had required, did not train staff and did not pass on safety information."),
   S(180,170,True,None,None,None,TFC,CIVIL)),
  D(L("Geschäftsführer / Verwaltungsratspräsident","Directeur / président du conseil d’administration","Direttore / presidente del CdA","Managing director / board chair"),FT,"convicted",
   L("Kontrollierte nicht, ob der Sicherheitsbeauftragte seine Aufgaben erfüllte.","N’a pas contrôlé que le chargé de sécurité remplissait ses tâches.","Non ha controllato che l’incaricato della sicurezza svolgesse i suoi compiti.","Did not check that the safety officer was doing his job."),
   S(180,410,True,None,None,None,TFC,CIVIL))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-521-2025_2025-11-12.html","de"),
 L("Fahrgestell fällt vom Kran: Chef und Sicherheitsbeauftragter verurteilt","Un châssis tombe de la grue: le patron et le chargé de sécurité condamnés","Un telaio cade dalla gru: condannati capo e incaricato della sicurezza","Chassis falls from crane: boss and safety officer convicted"),
 L("Auf einem Werkhof wurde ein rund 2 Tonnen schweres Anhänger-Fahrgestell aus Stahl mit einem Kran angehoben. Es fiel herunter und tötete einen Arbeiter.","Dans un dépôt, un châssis de remorque en acier d’environ 2 tonnes soulevé par une grue est tombé et a tué un ouvrier.","In un deposito un telaio di rimorchio in acciaio di circa 2 tonnellate sollevato con una gru è caduto uccidendo un operaio.","At a company yard, a steel trailer chassis of about 2 tonnes lifted by crane fell and killed a worker."),
 FATAL,
 L("Die Arbeiter waren weder zur Absturzsicherung noch zum Gefahrenbereich unter schwebenden Lasten geschult. Ein Mitverschulden des Opfers entlastet die Vorgesetzten nicht, weil es gerade durch die fehlende Instruktion begünstigt wurde.","Les ouvriers n’étaient formés ni à la protection des bords ni à la zone dangereuse sous les charges suspendues. La faute de la victime n’exonère pas les supérieurs, car elle a été favorisée par le manque d’instruction.","Gli operai non erano formati né sulla protezione dei bordi né sulla zona di pericolo sotto i carichi sospesi. La colpa della vittima non scagiona i superiori, perché favorita dalla mancata istruzione.","Workers had not been trained on edge protection or the danger zone under suspended loads. The victim's own fault does not clear the managers, because the missing instruction encouraged it."),
 L("Nie unter schwebenden Lasten. Wer Sicherheit delegiert, muss kontrollieren, ob sie umgesetzt wird.","Jamais sous une charge suspendue. Qui délègue la sécurité doit contrôler qu’elle est appliquée.","Mai sotto carichi sospesi. Chi delega la sicurezza deve controllare che sia applicata.","Never under a suspended load. If you delegate safety, check that it is actually done.")))

new.append(R("2024-09-04-bger-6b-1190-2023-vd-geruest","2024-09-04","2014-03-25","VD","Lausanne","construction","fall","life_threatening",BGER,"6B_1190/2023",True,
 L("Beide in erster Instanz verurteilt; das Kantonsgericht Waadt reduzierte die Strafe des Bauleiters; das Bundesgericht wies beide Beschwerden ab – rechtskräftig.","Tous deux condamnés en première instance; la Cour d’appel vaudoise a réduit la peine du directeur des travaux; recours rejetés par le TF – définitif.","Entrambi condannati in prima istanza; la Corte d’appello vodese ha ridotto la pena del direttore dei lavori; ricorsi respinti dal TF – definitivo.","Both convicted at first instance; the Vaud appeal court cut the works director's sentence; Federal Court dismissed both appeals – final."),
 L("Generalunternehmer und Gerüstbaufirma; Unternehmen nicht angeklagt.","Entreprise générale et entreprise d’échafaudage; entreprises non prévenues.","Impresa generale e ditta di ponteggi; aziende non imputate.","General contractor and scaffolding firm; companies not charged."),
 [D(L("Bauleiter des Generalunternehmers","Directeur des travaux de l’entreprise générale","Direttore dei lavori dell’impresa generale","Works director, general contractor"),FKV,"convicted",
   L("Musste dafür sorgen, dass das Gerüst sicher montiert und unterhalten wird, und der Gerüstfirma Anweisungen geben.","Devait veiller au montage et à la maintenance sûrs de l’échafaudage et donner des instructions à l’entreprise d’échafaudage.","Doveva garantire montaggio e manutenzione sicuri del ponteggio e dare istruzioni alla ditta di ponteggi.","Had to make sure the scaffold was safely erected and maintained and to instruct the scaffolding firm."),
   S(50,100,True,2,None,None,TFC,L("Zivilhaftung dem Grundsatz nach; Parteientschädigung CHF 40’395.65, zu je einem Drittel","Responsabilité civile sur le principe; indemnité de CHF 40’395.65, par tiers","Responsabilità civile in linea di principio; indennità di CHF 40’395.65, per un terzo ciascuno","Civil liability in principle; party costs CHF 40,395.65, one third each"))),
  D(L("Technischer Leiter der Gerüstbaufirma","Directeur technique de l’entreprise d’échafaudage","Direttore tecnico della ditta di ponteggi","Technical director, scaffolding firm"),FKV,"convicted",
   L("Verantwortlich dafür, dass das Gerüst mit Sicherungsstiften und befestigten Bordbrettern montiert ist.","Responsable d’un échafaudage monté avec goupilles de sécurité et plinthes fixées.","Responsabile di un ponteggio montato con spine di sicurezza e tavole fermapiede fissate.","Responsible for the scaffold being erected with locking pins and fixed toe boards."),
   S(100,100,True,2,None,None,TFC,L("Zivilhaftung dem Grundsatz nach","Responsabilité civile sur le principe","Responsabilità civile in linea di principio","Civil liability in principle")))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-1190-2023_2024-09-04.html","fr"),
 L("Gerüstbelag kippt: Bauleiter und Gerüstfirma verurteilt","Un plateau d’échafaudage bascule: directeur des travaux et échafaudeur condamnés","Si ribalta un piano del ponteggio: condannati direttore dei lavori e ditta di ponteggi","Scaffold deck tips: works director and scaffolder convicted"),
 L("Ein Dachdecker stürzte über 8 m ab, als eine Gerüstplattform ohne Sicherungsstifte und ohne befestigte Bordbretter kippte.","Un couvreur a chuté de plus de 8 m lorsqu’un plateau d’échafaudage sans goupilles ni plinthes fixées a basculé.","Un copritetto è caduto da oltre 8 m quando un piano del ponteggio senza spine né tavole fermapiede fissate si è ribaltato.","A roofer fell more than 8 m when a scaffold platform without locking pins or fixed toe boards tipped over."),
 L("Lebensgefährlich verletzt","Blessé, pronostic vital engagé","Ferito in pericolo di vita","Life-threatening injuries"),
 L("Beide hatten eine Pflicht zur sicheren Montage und Kontrolle des Gerüsts; der Bauleiter durfte sich nicht allein auf die Gerüstfirma verlassen.","Tous deux devaient assurer le montage et le contrôle sûrs de l’échafaudage; le directeur des travaux ne pouvait pas s’en remettre au seul échafaudeur.","Entrambi dovevano garantire montaggio e controllo sicuri del ponteggio; il direttore dei lavori non poteva affidarsi alla sola ditta di ponteggi.","Both had a duty to ensure the scaffold was safely erected and checked; the works director could not simply rely on the scaffolding firm."),
 L("Gerüst vor der Nutzung abnehmen: Beläge gesichert, Bordbretter fest? Auch der Bauleiter des Hauptunternehmers ist verantwortlich.","Réceptionner l’échafaudage avant usage: plateaux bloqués, plinthes fixées? Le directeur des travaux de l’entreprise générale répond aussi.","Collaudare il ponteggio prima dell’uso: piani bloccati, fermapiede fissati? Risponde anche il direttore dei lavori dell’impresa generale.","Inspect scaffolds before use: decks locked, toe boards fixed? The main contractor's works director is responsible too.")))
new.append(R("2023-03-16-bger-6b-1386-2021-vd-gitterrost","2023-03-16","2016-09-26","VD",None,"construction","fall","fatal",BGER,"6B_1386/2021",True,
 L("Verurteilt in erster Instanz; das Kantonsgericht Waadt reduzierte die Strafe (1.6.2021); das Bundesgericht wies die Beschwerde ab – rechtskräftig.","Condamné en première instance; la Cour d’appel vaudoise a réduit la peine (1.6.2021); recours rejeté par le TF – définitif.","Condannato in prima istanza; la Corte d’appello vodese ha ridotto la pena (1.6.2021); ricorso respinto dal TF – definitivo.","Convicted at first instance; Vaud appeal court reduced the sentence (1.6.2021); Federal Court dismissed the appeal – final."),
 L("Metallbaufirma; der Verurteilte war ihr einziger Verwaltungsrat.","Entreprise de construction métallique; le condamné en était l’administrateur unique.","Impresa di costruzioni metalliche; il condannato ne era l’amministratore unico.","Steel construction firm; the defendant was its sole director."),
 [D(L("Einziger Verwaltungsrat und Leiter der Arbeiten","Administrateur unique et responsable des travaux","Amministratore unico e responsabile dei lavori","Sole director, in charge of the works"),FT,"convicted",
   L("Ordnete an, die Gitterroste nur provisorisch mit Klemmen zu befestigen, obwohl er gewarnt worden war – am selben Morgen wäre ein Kranführer beinahe gestürzt.","A fait fixer les caillebotis provisoirement avec des serre-joints malgré des avertissements – le matin même, un grutier avait failli chuter.","Ha fatto fissare i grigliati solo provvisoriamente con morsetti nonostante gli avvertimenti – la mattina stessa un gruista aveva rischiato di cadere.","Had the gratings fixed only provisionally with clamps despite warnings – that same morning a crane operator nearly fell."),
   S(60,130,True,2,None,L("12 Monate Freiheitsstrafe, bedingt","12 mois de peine privative de liberté avec sursis","12 mesi di detenzione sospesi","12 months' custody, suspended"),TFC,
     L("Genugtuung CHF 30’000 und CHF 15’000; Sachschaden CHF 7027","Tort moral CHF 30’000 et CHF 15’000; dommage matériel CHF 7027","Torto morale CHF 30’000 e CHF 15’000; danno materiale CHF 7027","Moral damages CHF 30,000 and CHF 15,000; material damage CHF 7,027")),
   short=L("Liess Gitterroste trotz Warnungen nur provisorisch befestigen.","A fait fixer les caillebotis provisoirement malgré des avertissements.","Ha fatto fissare i grigliati solo provvisoriamente nonostante gli avvertimenti.","Had gratings fixed only provisionally despite warnings."))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-1386-2021_2023-03-16.html","fr"),
 L("Lernender (18) stirbt nach Sturz über losen Gitterrost: Firmenchef verurteilt","Un apprenti de 18 ans meurt après la chute d’un caillebotis non fixé: le patron condamné","Apprendista di 18 anni muore per un grigliato non fissato: condannato il titolare","Apprentice (18) dies as loose grating slides: company boss convicted"),
 L("Ein 18-jähriger Metallbau-Lernender starb, als ein nicht befestigter Gitterrost auf der 3. Ebene einer Aussentreppe aus Stahl wegrutschte.","Un apprenti constructeur métallique de 18 ans est mort lorsqu’un caillebotis non fixé a glissé au 3e niveau d’un escalier extérieur en acier.","Un apprendista metalcostruttore di 18 anni è morto quando un grigliato non fissato è scivolato al 3° livello di una scala esterna in acciaio.","An 18-year-old apprentice metalworker died when an unfixed grating slid away on the 3rd level of an external steel staircase."),
 FATAL,
 L("Er kannte die Gefahr aus konkreten Warnungen und entschied sich trotzdem für eine provisorische Befestigung. Freigesprochen wurde er nur vom Vorwurf zu Schutzvorrichtungen.","Il connaissait le danger par des avertissements concrets et a malgré tout choisi une fixation provisoire. Il n’a été acquitté que du chef relatif aux dispositifs de protection.","Conosceva il pericolo da avvertimenti concreti e ha comunque scelto un fissaggio provvisorio. È stato assolto solo dall’accusa relativa ai dispositivi di protezione.","He knew the danger from concrete warnings and still chose a provisional fix. He was acquitted only on the protective-device charge."),
 L("Gitterroste und Abdeckungen sofort definitiv befestigen. Ein Beinahe-Unfall am Morgen ist ein Stoppsignal.","Fixer définitivement caillebotis et couvercles tout de suite. Un presque-accident le matin est un signal d’arrêt.","Fissare subito in modo definitivo grigliati e coperture. Un quasi-incidente al mattino è un segnale di stop.","Fix gratings and covers properly straight away. A near miss that morning is a stop signal.")))

new.append(R("2026-05-22-bger-6b-940-2024-vd-decoffrage","2026-05-22","2014-10-10","VD","La Côte","construction","fall","serious",BGER,"6B_940/2024",True,
 L("Erste Instanz verurteilte nur den Schalungschef; das Kantonsgericht verurteilte alle vier; das Bundesgericht sprach die zwei Schaler frei und bestätigte die Urteile gegen Polier und Schalungschef.","Seul le chef coffreur condamné en première instance; la Cour d’appel a condamné les quatre; le TF a acquitté les deux coffreurs et confirmé les condamnations du contremaître et du chef coffreur.","Solo il capo casseratore condannato in prima istanza; la Corte d’appello ha condannato tutti e quattro; il TF ha assolto i due casseratori e confermato le condanne di capocantiere e capo casseratore.","First instance convicted only the formwork foreman; the appeal court convicted all four; the Federal Court acquitted the two formworkers and upheld the site foreman's and formwork foreman's convictions."),
 L("Generalunternehmer (Rohbau) und Subunternehmer (Schalung); Unternehmen nicht angeklagt.","Entreprise générale (gros œuvre) et sous-traitant (coffrage); entreprises non prévenues.","Impresa generale (rustico) e subappaltatore (casseforme); aziende non imputate.","Main contractor (shell) and formwork subcontractor; companies not charged."),
 [D(L("Polier des Generalunternehmers","Chef de chantier / contremaître de l’entreprise générale","Capocantiere dell’impresa generale","Site foreman, main contractor"),FKV229,"convicted",
   L("Liess das Ausschalen beginnen, bevor das Geländer am Deckenrand stand, ohne Schutzmassnahmen und ohne Instruktion der Arbeiter.","A laissé commencer le décoffrage avant la pose du garde-corps, sans mesures de sécurité ni instructions aux ouvriers.","Ha lasciato iniziare il disarmo prima della posa del parapetto, senza misure di sicurezza né istruzioni agli operai.","Let stripping start before the edge railing was up, without safety measures or instructing the workers."),S(80,40,True,2,None,None,TFC,CIVIL)),
  D(L("Schalungschef des Subunternehmers","Chef coffreur du sous-traitant","Capo casseratore del subappaltatore","Formwork foreman, subcontractor"),FKV229,"convicted",
   L("Gab den Schalern nur den allgemeinen Auftrag auszuschalen, ohne Anweisungen zur Sicherheit.","N’a donné aux coffreurs qu’un ordre général de décoffrer, sans consigne de sécurité.","Ha dato ai casseratori solo l’ordine generico di disarmare, senza istruzioni di sicurezza.","Gave formworkers only a general order to strip, with no safety instructions."),S(120,40,True,2,None,None,TFC,CIVIL)),
  D(L("Schaler (2 Personen)","Coffreurs (2 personnes)","Casseratori (2 persone)","Formworkers (2 people)"),FKV229,"acquitted",
   L("Vom Bundesgericht freigesprochen; die Zivilforderungen gegen sie gehen zurück an das Kantonsgericht.","Acquittés par le TF; les prétentions civiles contre eux sont renvoyées à la cour cantonale.","Assolti dal TF; le pretese civili contro di loro tornano alla corte cantonale.","Acquitted by the Federal Court; civil claims against them go back to the cantonal court."),S())],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-940-2024_2026-05-22.html","fr"),
 L("Sturz durch ausgeschalte Decke: Polier und Schalungschef verurteilt, Schaler freigesprochen","Chute à travers un coffrage décoffré: contremaître et chef coffreur condamnés, coffreurs acquittés","Caduta attraverso un cassero disarmato: condannati capocantiere e capo casseratore, assolti i casseratori","Fall through stripped formwork: foremen convicted, formworkers acquitted"),
 L("Ein Hilfsarbeiter, der am Deckenrand ein Geländer montierte, trat auf ein Schalungspanel, unter dem die Stützen bereits entfernt waren. Er stürzte rund 4,25 m ab.","Un manœuvre qui posait un garde-corps en bord de dalle a marché sur un panneau de coffrage dont les étais avaient déjà été retirés. Il a chuté d’environ 4,25 m.","Un manovale che montava un parapetto al bordo della soletta ha calpestato un pannello di cassero già privo di puntelli. È caduto da circa 4,25 m.","A labourer fitting a railing at the slab edge stepped onto a formwork panel whose props had already been removed. He fell about 4.25 m."),
 L("Schwer verletzt","Blessé grièvement","Ferito gravemente","Seriously injured"),
 L("Die Verantwortung lag bei den Vorgesetzten, die Arbeiten koordinieren und Sicherheit anordnen mussten. Die Verantwortung des Subunternehmers entlastet den Polier des Generalunternehmers nicht.","La responsabilité incombait aux supérieurs, qui devaient coordonner les travaux et ordonner la sécurité. Celle du sous-traitant ne décharge pas le contremaître de l’entreprise générale.","La responsabilità era dei superiori, che dovevano coordinare i lavori e disporre la sicurezza. Quella del subappaltatore non scarica il capocantiere dell’impresa generale.","Responsibility lay with the supervisors who had to coordinate work and order safety measures. The subcontractor's responsibility does not relieve the main contractor's foreman."),
 L("Erst Absturzsicherung, dann ausschalen. Wer Schalung entfernt, sperrt und meldet die Zone – allen Gewerken.","D’abord la protection antichute, ensuite le décoffrage. Qui décoffre ferme et annonce la zone à tous les corps de métier.","Prima la protezione anticaduta, poi il disarmo. Chi disarma chiude e segnala la zona a tutti.","Edge protection first, then strip. Whoever strips formwork closes the zone and tells every trade.")))
new.append(R("2025-10-29-bger-6b-740-2024-ne-rollgeruest","2025-10-29","2022-06-13","NE",None,"construction","fall","fatal",
 L("Bundesgericht / Kantonsgericht Neuenburg","Tribunal fédéral / Tribunal cantonal neuchâtelois","Tribunale federale / Tribunale cantonale neocastellano","Federal Supreme Court / Neuchâtel Cantonal Court"),"6B_740/2024; CPEN.2023.80",True,
 L("Erste Instanz: fahrlässige Tötung. Das Kantonsgericht (24.4.2024) sprach davon frei und verurteilte wegen fahrlässiger Verletzung der Regeln der Baukunde. Das Bundesgericht trat auf die Beschwerde der Angehörigen nicht ein – rechtskräftig.","Première instance: homicide par négligence. Le Tribunal cantonal (24.4.2024) l’a acquitté de ce chef et condamné pour violation par négligence des règles de l’art de construire. Le TF a déclaré irrecevable le recours des proches – définitif.","Prima istanza: omicidio colposo. Il Tribunale cantonale (24.4.2024) lo ha assolto da tale accusa e condannato per violazione colposa delle regole dell’arte edilizia. Il TF ha dichiarato irricevibile il ricorso dei congiunti – definitivo.","First instance: negligent homicide. The Cantonal Court (24.4.2024) acquitted him of that and convicted him of negligently breaching building rules. The Federal Court declared the relatives' appeal inadmissible – final."),
 L("Malerbetrieb; Opfer war als Temporärarbeiter eingesetzt.","Entreprise de peinture; la victime était un intérimaire.","Impresa di pittura; la vittima era un lavoratore interinale.","Painting firm; the victim was a temporary worker."),
 [D(L("Technischer Leiter, leitete die Baustelle","Responsable technique, dirigeant le chantier","Responsabile tecnico, dirigeva il cantiere","Technical manager running the site"),R229,"convicted",
   L("Wusste, dass das Rollgerüst Seitenschutz und Stützen brauchte, und unterschätzte die Gefahr. Von der fahrlässigen Tötung freigesprochen.","Savait que le pont roulant devait avoir protections latérales et béquilles et a sous-estimé le danger. Acquitté de l’homicide par négligence.","Sapeva che il ponte mobile richiedeva protezioni laterali e stabilizzatori e ha sottovalutato il pericolo. Assolto dall’omicidio colposo.","Knew the mobile scaffold needed side protection and outriggers and underestimated the danger. Acquitted of negligent homicide."),
   S(40,100,True,2,None,None,None,L("Zivilforderungen der Angehörigen abgewiesen","Conclusions civiles des proches rejetées","Pretese civili dei congiunti respinte","Relatives' civil claims rejected")))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-740-2024_2025-10-29.html","fr"),
 L("Leiter rutscht auf Rollgerüst: Bauleiter wegen Baukunde-Verstoss verurteilt","Une échelle glisse sur un pont roulant: condamnation pour violation des règles de l’art","Una scala scivola su un ponte mobile: condanna per violazione delle regole edilizie","Ladder slips on mobile scaffold: site manager convicted of breaching building rules"),
 L("Ein Maler stand mit einer Leiter auf einem Rollgerüst ohne Seitenschutz und Stützen. Die Leiter rutschte, das Gerüst kippte, er stürzte rund 4 m ab und starb.","Un peintre se tenait sur une échelle posée sur un pont roulant sans protections latérales ni béquilles. L’échelle a glissé, le pont a basculé; il a chuté d’environ 4 m et est décédé.","Un pittore stava su una scala appoggiata a un ponte mobile senza protezioni né stabilizzatori. La scala è scivolata, il ponte si è ribaltato; è caduto da circa 4 m ed è morto.","A painter stood on a ladder placed on a mobile scaffold without side protection or outriggers. The ladder slipped, the scaffold tipped, he fell about 4 m and died."),
 FATAL,
 L("Das ungesicherte Rollgerüst war eine konkrete Gefahr für die Arbeiter, unabhängig vom Verhalten des Opfers. Der Freispruch vom Tötungsvorwurf wurde nicht mehr überprüft, weil das Bundesgericht nicht auf die Beschwerde eintrat.","Le pont roulant non conforme mettait concrètement les ouvriers en danger, quel que soit le comportement de la victime. L’acquittement d’homicide n’a pas été revu, le TF n’étant pas entré en matière.","Il ponte mobile non conforme metteva concretamente in pericolo gli operai, indipendentemente dal comportamento della vittima. L’assoluzione per omicidio non è stata riesaminata, il TF non essendo entrato nel merito.","The non-compliant mobile scaffold put workers in concrete danger, whatever the victim did. The homicide acquittal was not reviewed because the Federal Court did not hear the appeal."),
 L("Keine Leiter auf ein Rollgerüst stellen. Rollgerüste nur mit Seitenschutz und ausgefahrenen Stützen.","Jamais d’échelle sur un pont roulant. Pont roulant uniquement avec garde-corps et béquilles déployées.","Mai una scala su un ponte mobile. Ponte mobile solo con parapetti e stabilizzatori aperti.","Never put a ladder on a mobile scaffold. Use mobile scaffolds only with guardrails and outriggers deployed."),
 extra=[ES("https://entscheidsuche.ch/docs/NE_Omni/NE_TC_009_CPEN-2023-80_2024-04-24.html","fr")]))

new.append(R("2024-09-11-bger-7b-14-2023-vd-hotel","2024-09-11","2015-11-12","VD","Lausanne","construction","fall","serious",BGER,"7B_14/2023",True,
 L("Alle drei in erster Instanz verurteilt (29.11.2021); Berufungen abgewiesen (17.8.2022); Bundesgericht wies die Beschwerden ab – rechtskräftig.","Les trois condamnés en première instance (29.11.2021); appels rejetés (17.8.2022); recours rejetés par le TF – définitif.","Tutti e tre condannati in prima istanza (29.11.2021); appelli respinti (17.8.2022); ricorsi respinti dal TF – definitivo.","All three convicted at first instance (29.11.2021); appeals dismissed (17.8.2022); Federal Court dismissed the appeals – final."),
 L("Bauherrschaft (Hotel) und Bauleitungsfirma; Unternehmen nicht angeklagt.","Maître d’ouvrage (hôtel) et bureau de direction des travaux; entreprises non prévenues.","Committente (albergo) e studio di direzione lavori; aziende non imputate.","Client (hotel) and site-management firm; companies not charged."),
 [D(L("Projektleiter der Bauherrschaft","Directeur de projet du maître d’ouvrage","Direttore di progetto del committente","Client's project director"),FKV,"convicted",
   L("Bestimmte keinen fachkundigen Sicherheitsverantwortlichen für die Baustelle.","N’a pas désigné de responsable sécurité compétent pour le chantier.","Non ha designato un responsabile della sicurezza competente.","Did not appoint a competent safety officer for the site."),S(50,100,True,2,None,None,TFC,CIVIL)),
  D(L("Bauleiter (Spa-Bereich)","Directeur des travaux (secteur spa)","Direttore dei lavori (settore spa)","Works manager (spa area)"),FKV,"convicted",
   L("War für die Sicherheit im Spa-Bereich zuständig; hat das Urteil nicht angefochten.","Responsable de la sécurité du secteur spa; n’a pas fait appel.","Responsabile della sicurezza del settore spa; non ha impugnato.","Responsible for safety in the spa area; did not appeal."),S(60,100,True,2,None,None,None,CIVIL)),
  D(L("Teilhaber der Bauleitungsfirma (Oberaufsicht)","Associé du bureau de direction des travaux (supervision)","Socio dello studio di direzione lavori (supervisione)","Partner of the site-management firm (overall supervision)"),FKV,"convicted",
   L("Hatte die Oberaufsicht und war nach einem Personalwechsel auch für den Spa-Bereich verantwortlich.","Avait la supervision générale et répondait aussi du spa après un départ.","Aveva la supervisione generale e rispondeva anche della spa dopo una partenza.","Had overall supervision and, after a staff departure, also the spa area."),S(30,150,True,2,None,None,TFC,CIVIL))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_007_7B-14-2023_2024-09-11.html","fr"),
 L("Ungesichertes Treppenloch im Hotelumbau: drei Verantwortliche verurteilt","Cage d’escalier non protégée dans un hôtel en travaux: trois responsables condamnés","Vano scale non protetto in un albergo in cantiere: tre responsabili condannati","Unprotected stairwell in hotel renovation: three managers convicted"),
 L("Ein Plattenleger stieg über einen Metallkanister auf eine provisorische Holzplattform vor einem ungesicherten Treppenloch. Der Kanister rutschte weg und er stürzte 4,5 m ab.","Un carreleur est monté sur un bidon métallique pour atteindre une plateforme provisoire devant une cage d’escalier sans protection. Le bidon a glissé et il a chuté de 4,5 m.","Un piastrellista è salito su un bidone metallico per raggiungere una piattaforma provvisoria davanti a un vano scale non protetto. Il bidone è scivolato ed è caduto da 4,5 m.","A tiler stepped on a metal drum to reach a makeshift wooden platform at an unprotected stairwell. The drum slid and he fell 4.5 m."),
 L("Wirbel- und Beckenbrüche, Beine gelähmt, 100 % invalid","Fractures des vertèbres et du bassin, perte de l’usage des jambes, invalidité 100 %","Fratture di vertebre e bacino, perdita dell’uso delle gambe, invalidità 100 %","Spinal and pelvic fractures, lost use of legs, 100 % disability"),
 L("Viele benutzten diesen improvisierten Zugang. Wer Sicherheit auf einer Grossbaustelle organisiert, muss fachkundige Personen einsetzen und die eigenen Bereiche kontrollieren.","Beaucoup utilisaient ce passage improvisé. Qui organise la sécurité d’un grand chantier doit nommer des personnes compétentes et contrôler ses secteurs.","Molti usavano questo passaggio improvvisato. Chi organizza la sicurezza di un grande cantiere deve nominare persone competenti e controllare i propri settori.","Many people used this improvised access. Whoever organises safety on a large site must appoint competent people and check their areas."),
 L("Improvisierte Durchgänge sind Warnsignale. Öffnungen sofort sichern – und für Sicherheit eine fachkundige Person benennen.","Les passages improvisés sont des signaux d’alarme. Protéger les ouvertures tout de suite et nommer une personne compétente pour la sécurité.","I passaggi improvvisati sono segnali d’allarme. Proteggere subito le aperture e nominare una persona competente per la sicurezza.","Improvised routes are warning signs. Protect openings at once and name a competent person for safety.")))
new.append(R("2024-06-07-bger-7b-62-2023-vd-faserzement","2024-06-07","2017-05-17","VD",None,"construction","fall","fatal",BGER,"7B_62/2023",True,
 L("Erste Instanz: 3 Jahre, davon 18 Monate unbedingt. Das Kantonsgericht reduzierte auf 30 Monate (15 unbedingt). Das Bundesgericht wies die Beschwerden des Verurteilten und der Staatsanwaltschaft ab – rechtskräftig.","Première instance: 3 ans dont 18 mois ferme. La Cour d’appel a réduit à 30 mois (dont 15 ferme). Le TF a rejeté les recours du condamné et du Ministère public – définitif.","Prima istanza: 3 anni, di cui 18 mesi da scontare. La Corte d’appello ha ridotto a 30 mesi (15 da scontare). Il TF ha respinto i ricorsi del condannato e del Ministero pubblico – definitivo.","First instance: 3 years, 18 months unsuspended. Appeal court cut it to 30 months (15 to serve). Federal Court dismissed both the defendant's and the prosecutor's appeals – final."),
 L("Abdichtungsfirma; die Suva hatte sie 2010–2013 fünfmal ermahnt und 2012 verwarnt.","Entreprise d’étanchéité; la Suva était intervenue cinq fois entre 2010 et 2013 et l’avait avertie en 2012.","Impresa di impermeabilizzazione; la Suva era intervenuta cinque volte tra il 2010 e il 2013 e l’aveva ammonita nel 2012.","Waterproofing firm; Suva had intervened five times in 2010–2013 and issued a warning in 2012."),
 [D(L("Geschäftsführer","Directeur de l’entreprise","Direttore dell’azienda","Company director"),L("Fahrlässige Tötung, vorsätzliche Verletzung der Regeln der Baukunde (und ein separates Strassenverkehrsdelikt)","Homicide par négligence, violation intentionnelle des règles de l’art de construire (et une infraction routière distincte)","Omicidio colposo, violazione intenzionale delle regole edilizie (e un’infrazione stradale distinta)","Negligent homicide, intentional breach of building rules (and a separate road-traffic offence)"),"convicted",
   L("Trotz mehrfacher Suva-Ermahnungen traf er keine Massnahmen gegen Absturz durch das Faserzementdach und beurteilte nichts neu, als ihm gemeldet wurde, dass die Arbeit nicht von der Hebebühne aus ging.","Malgré plusieurs interventions de la Suva, il n’a pris aucune mesure contre les chutes à travers le toit en fibrociment et n’a rien réévalué quand on lui a signalé que le travail ne pouvait pas se faire depuis la nacelle.","Nonostante vari interventi della Suva non ha preso misure contro le cadute attraverso il tetto in fibrocemento e non ha rivalutato nulla quando gli è stato detto che il lavoro non si poteva fare dalla piattaforma.","Despite repeated Suva warnings he took no measures against falls through the fibre-cement roof, and re-assessed nothing when told the job could not be done from the lift."),
   S(60,10,False,None,None,L("30 Monate Freiheitsstrafe: 15 unbedingt, 15 bedingt (4 Jahre Probezeit)","30 mois de peine privative de liberté: 15 ferme, 15 avec sursis (4 ans)","30 mesi di detenzione: 15 da scontare, 15 sospesi (4 anni)","30 months' custody: 15 to serve, 15 suspended (4 years' probation)"),TFC),
   short=L("Ignorierte wiederholte Suva-Ermahnungen zur Absturzsicherung auf Faserzementdächern.","A ignoré les avertissements répétés de la Suva sur les chutes à travers les toits en fibrociment.","Ha ignorato ripetuti avvertimenti della Suva sulle cadute attraverso tetti in fibrocemento.","Ignored repeated Suva warnings about falls through fibre-cement roofs."))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_007_7B-62-2023_2024-06-07.html","fr"),
 L("Durchbruch durch Faserzementdach: Firmenchef muss ins Gefängnis","Chute à travers un toit en fibrociment: le patron condamné à de la prison ferme","Caduta attraverso un tetto in fibrocemento: il titolare condannato al carcere","Fall through fibre-cement roof: company boss gets prison time"),
 L("Zwei angelernte Arbeiter ersetzten Faserzementplatten und gingen direkt auf dem Dach, weil die Arbeit von der Hebebühne aus nicht ging. Einer trat in eine Öffnung, brach durch die Isolation und stürzte 9,4 m ab; er starb am Folgetag.","Deux ouvriers formés sur le tas remplaçaient des plaques en fibrociment en marchant sur le toit, le travail étant impossible depuis la nacelle. L’un a mis le pied dans une ouverture, a traversé l’isolation et a chuté de 9,4 m; il est mort le lendemain.","Due operai formati sul campo sostituivano lastre in fibrocemento camminando sul tetto, poiché dalla piattaforma il lavoro era impossibile. Uno ha messo il piede in un’apertura, ha sfondato l’isolamento ed è caduto da 9,4 m; è morto il giorno dopo.","Two workers trained on the job were replacing fibre-cement sheets, walking on the roof because the job could not be done from the lift. One stepped into an opening, went through the insulation and fell 9.4 m; he died the next day."),
 FATAL,
 L("Er war mehrfach gewarnt worden und kannte die Gefahr. Die Strafe umfasst auch ein separates Strassenverkehrsdelikt.","Il avait été averti à plusieurs reprises et connaissait le danger. La peine couvre aussi une infraction routière distincte.","Era stato avvertito più volte e conosceva il pericolo. La pena copre anche un’infrazione stradale distinta.","He had been warned repeatedly and knew the danger. The sentence also covers a separate road-traffic offence."),
 L("Faserzementdächer sind nicht durchbruchsicher: Laufstege, Auffangnetze oder Arbeit von unten. Ändert sich der Arbeitsablauf, Massnahmen neu beurteilen.","Les toits en fibrociment ne résistent pas à la rupture: passerelles, filets ou travail par-dessous. Si la méthode change, réévaluer les mesures.","I tetti in fibrocemento non sono resistenti: passerelle, reti o lavoro da sotto. Se cambia il metodo, rivalutare le misure.","Fibre-cement roofs are not walk-safe: crawling boards, nets, or work from below. If the method changes, re-assess the measures.")))

new.append(R("2024-02-14-bger-7b-744-2023-ne-faux-plafond","2024-02-14","2019-01-25","NE",None,"construction","fall","serious",BGER,"7B_744/2023",True,
 L("Verurteilt in erster Instanz (31.5.2021); Berufung abgewiesen (21.12.2022); Bundesgericht wies die Beschwerde ab – rechtskräftig.","Condamné en première instance (31.5.2021); appel rejeté (21.12.2022); recours rejeté par le TF – définitif.","Condannato in prima istanza (31.5.2021); appello respinto (21.12.2022); ricorso respinto dal TF – definitivo.","Convicted at first instance (31.5.2021); appeal dismissed (21.12.2022); Federal Court dismissed the appeal – final."),
 L("Ingenieurbüro mit Bauleitung; Opfer war ein selbständiger Restaurator.","Bureau d’ingénieurs chargé de la direction des travaux; la victime était un restaurateur indépendant.","Studio d’ingegneria con la direzione lavori; la vittima era un restauratore indipendente.","Engineering firm running the site; the victim was a self-employed restorer."),
 [D(L("Bauleiter (Bauingenieur)","Directeur des travaux (ingénieur civil)","Direttore dei lavori (ingegnere civile)","Site manager (civil engineer)"),FKV,"convicted",
   L("Sicherte einen Raum mit nicht tragfähigem Boden nur mit einem diagonal genagelten Brett, ohne Warnung oder Zutrittsverbot, obwohl er wusste, dass der Restaurator kommen würde.","N’a protégé une pièce au sol non porteur que par une planche clouée en diagonale, sans signalisation ni interdiction, alors qu’il savait que le restaurateur viendrait.","Ha protetto una stanza con pavimento non portante solo con un’asse inchiodata in diagonale, senza segnali né divieti, pur sapendo che il restauratore sarebbe venuto.","Secured a room with a non-load-bearing floor only with a diagonal plank, with no warning sign or ban, though he knew the restorer was coming."),
   S(40,100,True,2,None,None,L("Verfahrenskosten CHF 5263; Bundesgerichtskosten CHF 3000","Frais CHF 5263; frais du TF CHF 3000","Spese CHF 5263; spese TF CHF 3000","Costs CHF 5,263; Federal Court costs CHF 3,000"),L("Parteientschädigung an das Opfer CHF 7586.80","Indemnité à la victime CHF 7586.80","Indennità alla vittima CHF 7586.80","Party costs to the victim CHF 7,586.80")),
   short=L("Sperrte einen Raum mit nicht tragfähigem Boden nur mit einem Brett ab, ohne Warnschild.","N’a protégé une pièce au sol non porteur que par une planche, sans signalisation.","Ha protetto una stanza con pavimento non portante solo con un’asse, senza segnali.","Blocked a room with a non-load-bearing floor only with a plank, no warning sign."))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_007_7B-744-2023_2024-02-14.html","fr"),
 L("Durch Zwischendecke gestürzt: Bauleiter verurteilt","Chute à travers un faux plafond: le directeur des travaux condamné","Caduta attraverso un controsoffitto: condannato il direttore dei lavori","Fall through false ceiling: site manager convicted"),
 L("Ein Restaurator sollte in einem Altbau Balken reinigen. Er umging ein quer genageltes Brett, betrat den Raum und brach durch einen vermeintlichen Boden, der nur eine Zwischendecke war – rund 5 m tief.","Un restaurateur devait nettoyer des poutres dans un bâtiment ancien en rénovation. Il a contourné une planche clouée en travers, est entré et a traversé ce qui n’était qu’un faux plafond – environ 5 m.","Un restauratore doveva pulire travi in un edificio antico in ristrutturazione. Ha aggirato un’asse inchiodata, è entrato ed è precipitato attraverso un controsoffitto – circa 5 m.","A restorer was to clean beams in an old building under renovation. He stepped round a plank nailed across the doorway and fell through what was only a false ceiling – about 5 m."),
 L("Wirbelbruch, unvollständige Querschnittlähmung","Fracture des vertèbres, paraplégie incomplète","Frattura vertebrale, paraplegia incompleta","Spinal fracture, incomplete paraplegia"),
 L("Ein leicht umgehbares Brett ist keine ausreichende Absperrung. Der Bauleiter wusste vom Einsatz und hätte die Gefahr klar kennzeichnen oder den Zugang verhindern müssen.","Une planche facile à contourner n’est pas une barrière suffisante. Le directeur des travaux connaissait l’intervention et devait signaler clairement le danger ou bloquer l’accès.","Un’asse facilmente aggirabile non è una barriera sufficiente. Il direttore dei lavori sapeva dell’intervento e doveva segnalare chiaramente il pericolo o impedire l’accesso.","A plank you can step round is not a barrier. The site manager knew about the visit and had to mark the danger clearly or block access."),
 L("Nicht tragfähige Böden fest absperren und beschriften – besonders wenn externe Fachleute kommen.","Barrer solidement et signaler les sols non porteurs – surtout quand viennent des intervenants externes.","Sbarrare saldamente e segnalare i pavimenti non portanti – soprattutto quando arrivano esterni.","Firmly block and label floors that won't bear weight – especially when outside specialists come.")))
new.append(R("2025-03-05-ge-cj-p-5337-2018-kranlastwagen","2025-03-05","2018-03-18","GE",None,"construction","crane","serious",GECJ,"P/5337/2018 (AARP/80/2025)",None,
 L("Polizeigericht (29.7.2024): je 7 Monate Freiheitsstrafe bedingt. Die Berufungskammer ersetzte das durch bedingte Geldstrafen; Schuldsprüche bestätigt. Weiterzug nicht berichtet.","Tribunal de police (29.7.2024): 7 mois avec sursis chacun. La Chambre d’appel a remplacé par des peines pécuniaires avec sursis; culpabilités confirmées. Recours ultérieur non rapporté.","Tribunale di polizia (29.7.2024): 7 mesi sospesi ciascuno. La Camera d’appello li ha sostituiti con pene pecuniarie sospese; colpevolezze confermate. Ulteriore ricorso non riportato.","Police court (29.7.2024): 7 months suspended each. The appeal chamber replaced these with suspended day-fines; convictions upheld. Further appeal not reported."),
 L("Zimmereifirma (Arbeitgeber) und Lieferant mit Kranlastwagen; Unternehmen nicht angeklagt.","Entreprise de charpente (employeur) et fournisseur avec camion-grue; entreprises non prévenues.","Carpenteria (datore di lavoro) e fornitore con autogru; aziende non imputate.","Carpentry firm (employer) and supplier with crane truck; companies not charged."),
 [D(L("Fahrer und Kranführer des Lieferanten","Chauffeur et grutier du fournisseur","Autista e gruista del fornitore","Supplier's driver and crane operator"),FKV,"convicted",
   L("Bediente den Kran von einem Steuerstand ohne Sicht auf Haken und Ladefläche und ohne Einweiser, entgegen Betriebsanleitung und Baustellenreglement.","A manœuvré la grue depuis un poste sans vue sur le crochet et le plateau, sans guide, contrairement au manuel et au règlement sur les chantiers.","Ha manovrato la gru da una postazione senza vista su gancio e pianale, senza segnalatore, contro manuale e regolamento cantieri.","Operated the crane from a control post with no view of the hook or deck and no signaller, against the manual and site rules."),
   S(180,30,True,3,None,None,L("Ein Drittel der erstinstanzlichen Kosten (CHF 3995.90)","Un tiers des frais de première instance (CHF 3995.90)","Un terzo delle spese di prima istanza (CHF 3995.90)","One third of first-instance costs (CHF 3,995.90)"),
     L("Genugtuung CHF 160’000 solidarisch (1. Instanz); Parteientschädigungen CHF 19’514.10 und CHF 4125.80","Tort moral CHF 160’000 solidairement (1re instance); indemnités CHF 19’514.10 et CHF 4125.80","Torto morale CHF 160’000 in solido (1ª istanza); indennità CHF 19’514.10 e CHF 4125.80","Moral damages CHF 160,000 jointly (first instance); party costs CHF 19,514.10 and CHF 4,125.80")),
   short=L("Hob die Last ohne Sicht und ohne Einweiser an.","A levé la charge sans visibilité et sans guide.","Ha sollevato il carico senza visibilità e senza segnalatore.","Lifted the load without a view and without a signaller.")),
  D(L("Leiter des Arbeitgebers","Responsable de l’entreprise employeuse","Responsabile dell’azienda datrice di lavoro","Head of the employer"),FKV,"convicted",
   L("Verletzte als Arbeitgeber seine Pflichten aus der Unfallverhütungsverordnung (VUV) beim Abladen.","A violé, comme employeur, ses obligations selon l’OPA lors du déchargement.","Ha violato, come datore di lavoro, i suoi obblighi OPI durante lo scarico.","As employer, breached his duties under the accident-prevention ordinance during the unloading."),
   S(140,110,True,3,None,None,None,L("Genugtuung solidarisch (siehe oben); Parteientschädigungen","Tort moral solidaire (voir ci-dessus); indemnités","Torto morale in solido (vedi sopra); indennità","Moral damages jointly (see above); party costs"),L("Zusatzstrafe zu einem Strafbefehl von 2018","Peine complémentaire à une ordonnance de 2018","Pena aggiuntiva a un decreto del 2018","Additional sentence to a 2018 penalty order")))],
 ES("https://entscheidsuche.ch/docs/GE_Gerichte/GE_CJ_009_P-5337-2018_2025-03-05.pdf","fr"),
 L("Von Kranlast vom Lastwagen gestossen: Kranführer und Arbeitgeber verurteilt","Poussé du camion par la charge de la grue: grutier et employeur condamnés","Spinto giù dal camion dal carico della gru: condannati gruista e datore di lavoro","Pushed off truck by crane load: crane operator and employer convicted"),
 L("Beim Abladen von Isolationspaletten hob der Kranführer eine Last an, ohne den Arbeiter auf der Ladefläche zu sehen. Die Last stiess ihn vom Lastwagen; Warnrufe gingen im Lärm unter.","Lors du déchargement de palettes d’isolation, le grutier a levé une charge sans voir l’ouvrier resté sur le plateau. La charge l’a poussé du camion; les cris d’alerte se sont perdus dans le bruit.","Durante lo scarico di bancali isolanti il gruista ha sollevato un carico senza vedere l’operaio rimasto sul pianale. Il carico lo ha spinto giù dal camion; le grida di allarme si sono perse nel rumore.","Unloading insulation pallets, the crane operator lifted a load without seeing the worker still on the deck. The load pushed him off the truck; warning shouts were lost in the noise."),
 L("Vollständige Querschnittlähmung","Paraplégie complète","Paraplegia completa","Complete paraplegia"),
 L("Wer den Haken nicht sieht, braucht einen einzigen, klar erkennbaren Einweiser – so verlangt es die Betriebsanleitung. Der Arbeitgeber blieb für die Sicherheit seiner Leute beim Abladen verantwortlich.","Qui ne voit pas le crochet doit être guidé par une seule personne clairement identifiée, comme l’exige le manuel. L’employeur restait responsable de la sécurité de ses ouvriers au déchargement.","Chi non vede il gancio deve essere guidato da una sola persona ben riconoscibile, come chiede il manuale. Il datore di lavoro restava responsabile della sicurezza dei suoi operai allo scarico.","If you cannot see the hook you need one clearly identifiable signaller, as the manual requires. The employer remained responsible for his workers' safety during unloading."),
 L("Nie heben ohne Sicht auf die Last oder klaren Einweiser. Niemand auf der Ladefläche, wenn der Kran zieht.","Jamais de levage sans vue sur la charge ou sans guide. Personne sur le plateau quand la grue tire.","Mai sollevare senza vista sul carico o senza segnalatore. Nessuno sul pianale quando la gru tira.","Never lift without sight of the load or a clear signaller. Nobody on the deck while the crane pulls.")))

new.append(R("2026-03-02-ge-cj-p-10983-2021-coffrage","2026-03-02","2021-05-27","GE",None,"construction","fall","fatal",GECJ,"P/10983/2021 (AARP/74/2026)",None,
 L("Polizeigericht verurteilte (18.3.2025); die Berufungskammer hiess die Berufung teilweise gut, reduzierte die Strafe und bestätigte den Schuldspruch. Weiterzug nicht berichtet.","Condamné par le Tribunal de police (18.3.2025); appel partiellement admis, peine réduite, culpabilité confirmée. Recours ultérieur non rapporté.","Condannato dal Tribunale di polizia (18.3.2025); appello parzialmente accolto, pena ridotta, colpevolezza confermata. Ulteriore ricorso non riportato.","Convicted by the police court (18.3.2025); appeal partly upheld, sentence reduced, conviction confirmed. Further appeal not reported."),
 L("Rohbaufirma; Unternehmen nicht angeklagt.","Entreprise de gros œuvre; entreprise non prévenue.","Impresa di costruzioni grezze; azienda non imputata.","Shell-construction firm; company not charged."),
 [D(L("Maurer und Vorarbeiter Decke","Maçon et chef de dalle","Muratore e capo soletta","Mason and slab foreman"),FT,"convicted",
   L("Liess einen nicht fixierten Deckel über einer Öffnung verschieben, ohne Geländer oder andere kollektive Schutzmassnahmen – entgegen Bauarbeitenverordnung und Firmenregeln.","A fait déplacer un panneau non fixé couvrant une ouverture sans garde-corps ni autre protection collective – contrairement à l’OTConst et aux règles de l’entreprise.","Ha fatto spostare un pannello non fissato sopra un’apertura senza parapetti né altre protezioni collettive – contro l’OLCostr e le regole aziendali.","Had an unfixed panel over an opening moved without guardrails or other collective protection – against the construction ordinance and company rules."),
   S(None,None,True,3,None,L("8 Monate Freiheitsstrafe, bedingt","8 mois de peine privative de liberté avec sursis","8 mesi di detenzione sospesi","8 months' custody, suspended"),None,
     L("Genugtuung 2 × CHF 30’000 und 2 × CHF 6000; Sachschaden CHF 4520.40","Tort moral 2 × CHF 30’000 et 2 × CHF 6000; dommage matériel CHF 4520.40","Torto morale 2 × CHF 30’000 e 2 × CHF 6000; danno materiale CHF 4520.40","Moral damages 2 × CHF 30,000 and 2 × CHF 6,000; material damage CHF 4,520.40")),
   short=L("Liess eine Abdeckung über einer Öffnung ohne Absturzsicherung verschieben.","A fait déplacer la couverture d’une ouverture sans protection antichute.","Ha fatto spostare la copertura di un’apertura senza protezione anticaduta.","Had an opening's cover moved without fall protection."))],
 ES("https://entscheidsuche.ch/docs/GE_Gerichte/GE_CJ_009_P-10983-2021_2026-03-02.pdf","fr"),
 L("Abdeckung über Deckenöffnung verschoben: Vorarbeiter wegen fahrlässiger Tötung verurteilt","Couverture d’une trémie déplacée: le chef de dalle condamné pour homicide","Spostata la copertura di un’apertura: capo soletta condannato per omicidio colposo","Cover over slab opening moved: slab foreman convicted of negligent homicide"),
 L("Beim Anzeichnen auf einer Deckenschalung sollte ein Maurer ein nicht befestigtes Panel über einer Öffnung verschieben. Er verlor das Gleichgewicht, stürzte 5,36 m auf Beton und starb am nächsten Tag.","En traçant sur un coffrage de dalle, un maçon devait déplacer un panneau non fixé couvrant une ouverture. Il a perdu l’équilibre, chuté de 5,36 m sur le béton et est mort le lendemain.","Tracciando su una cassaforma di soletta, un muratore doveva spostare un pannello non fissato sopra un’apertura. Ha perso l’equilibrio, è caduto per 5,36 m sul cemento ed è morto il giorno dopo.","While marking out on slab formwork, a mason was told to move an unfixed panel over an opening. He lost his balance, fell 5.36 m onto concrete and died the next day."),
 FATAL,
 L("Öffnungen müssen Seitenschutz oder eine fest fixierte, bruchsichere Abdeckung haben. Wer eine Abdeckung verschieben lässt, muss vorher kollektiven Schutz einrichten.","Les ouvertures doivent avoir une protection latérale ou une couverture fixée et résistante. Qui fait déplacer une couverture doit d’abord installer une protection collective.","Le aperture devono avere una protezione laterale o una copertura fissata e resistente. Chi fa spostare una copertura deve prima installare una protezione collettiva.","Openings need side protection or a fixed, unbreakable cover. Whoever has a cover moved must first set up collective protection."),
 L("Abdeckungen über Öffnungen festschrauben und beschriften. Wird eine geöffnet: zuerst Geländer.","Visser et marquer les couvercles de trémies. Si on en ouvre un: d’abord le garde-corps.","Avvitare e segnalare le coperture delle aperture. Se se ne apre una: prima il parapetto.","Screw down and label covers over openings. If one is opened: guardrail first.")))
new.append(R("2026-06-24-bger-6b-657-2024-sz-dach","2026-06-24","2020-01-09","SZ",None,"construction","fall","serious",BGER,"6B_657/2024",False,
 L("Bezirksgericht March und Kantonsgericht Schwyz (18.6.2024) verurteilten beide wegen vorsätzlicher Gefährdung durch Verletzung der Regeln der Baukunde und sprachen sie von Körperverletzung frei. Das Bundesgericht hob das Urteil auf und wies den Fall zurück – Ausgang offen.","Le Tribunal de district de March et le Tribunal cantonal de Schwyz (18.6.2024) les ont condamnés pour violation intentionnelle des règles de l’art de construire et acquittés des lésions corporelles. Le TF a annulé et renvoyé l’affaire – issue ouverte.","Il Tribunale distrettuale di March e il Tribunale cantonale di Svitto (18.6.2024) li hanno condannati per violazione intenzionale delle regole edilizie e assolti dalle lesioni. Il TF ha annullato e rinviato il caso – esito aperto.","March District Court and the Schwyz Cantonal Court (18.6.2024) convicted both of intentionally breaching building rules and acquitted them of bodily harm. The Federal Court quashed this and sent the case back – outcome open."),
 L("Bedachungsfirma; Unternehmen nicht angeklagt.","Entreprise de couverture; entreprise non prévenue.","Impresa di coperture; azienda non imputata.","Roofing firm; company not charged."),
 [D(L("Geschäftsführer","Directeur","Direttore","Managing director"),V229,"open",
   L("Vom Kantonsgericht verurteilt (120 Tagessätze à CHF 440 bedingt + CHF 13’200 Busse); vom Bundesgericht aufgehoben, neue Beurteilung ausstehend.","Condamné par le Tribunal cantonal (120 jours-amende à CHF 440 avec sursis + CHF 13’200 d’amende); annulé par le TF, nouveau jugement en attente.","Condannato dal Tribunale cantonale (120 aliquote da CHF 440 sospese + multa CHF 13’200); annullato dal TF, nuovo giudizio in attesa.","Convicted by the Cantonal Court (120 day-fines of CHF 440 suspended + CHF 13,200 fine); quashed by the Federal Court, new ruling pending."),S()),
  D(L("Vorarbeiter","Chef d’équipe","Caposquadra","Foreman"),V229,"open",
   L("Vom Kantonsgericht verurteilt (96 Tagessätze à CHF 200 bedingt + CHF 4800 Busse); vom Bundesgericht aufgehoben, neue Beurteilung ausstehend.","Condamné par le Tribunal cantonal (96 jours-amende à CHF 200 avec sursis + CHF 4800 d’amende); annulé par le TF, nouveau jugement en attente.","Condannato dal Tribunale cantonale (96 aliquote da CHF 200 sospese + multa CHF 4800); annullato dal TF, nuovo giudizio in attesa.","Convicted by the Cantonal Court (96 day-fines of CHF 200 suspended + CHF 4,800 fine); quashed by the Federal Court, new ruling pending."),S())],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-657-2024_2026-06-24.html","de"),
 L("Durch Faserzementdach gebrochen: Bundesgericht hebt Urteile auf","Chute à travers un toit en fibrociment: le TF annule les condamnations","Caduta attraverso un tetto in fibrocemento: il TF annulla le condanne","Fall through fibre-cement roof: Federal Court quashes convictions"),
 L("Beim Abbruch eines nicht durchbruchsicheren Faserzementdachs bewegten sich die Dachdecker auf Dachleitern. Einer trat neben die Leiter, brach durch eine Platte und stürzte rund 7,8 m ab.","Lors de la dépose d’un toit en fibrociment non résistant, les couvreurs se déplaçaient sur des échelles de toit. L’un a marché à côté, a traversé une plaque et chuté d’environ 7,8 m.","Durante lo smontaggio di un tetto in fibrocemento non resistente i copritetto si muovevano su scale da tetto. Uno ha messo il piede accanto, ha sfondato una lastra ed è caduto per circa 7,8 m.","Removing a fibre-cement roof that was not walk-safe, roofers moved on roof ladders. One stepped beside the ladder, broke through a sheet and fell about 7.8 m."),
 L("Verletzt (Ausmass im Urteil nicht zusammengefasst)","Blessé (gravité non résumée dans l’arrêt)","Ferito (entità non riassunta nella sentenza)","Injured (extent not summarised in the ruling)"),
 L("Das Bundesgericht hiess die Beschwerden der beiden Verurteilten gut und wies den Fall zurück; das Kantonsgericht muss neu urteilen.","Le TF a admis les recours des deux condamnés et renvoyé l’affaire; le Tribunal cantonal doit rejuger.","Il TF ha accolto i ricorsi dei due condannati e rinviato il caso; il Tribunale cantonale deve rigiudicare.","The Federal Court upheld both appeals and sent the case back; the Cantonal Court must rule again."),
 L("Dachleitern allein schützen nicht vor Durchbruch: Auffangnetze oder Laufstege über die ganze Fläche.","Les échelles de toit seules ne protègent pas contre la rupture: filets ou passerelles sur toute la surface.","Le scale da tetto da sole non proteggono dallo sfondamento: reti o passerelle su tutta la superficie.","Roof ladders alone don't stop break-throughs: nets or crawling boards over the whole area.")))

new.append(R("2026-08-19-bger-6b-784-2025-ag-dachplatte","2026-08-19",None,"AG",None,"construction","fall","serious",BGER,"6B_784/2025",False,
 L("Strafbefehl gegen den Polier; Bezirksgericht Zurzach und Obergericht Aargau (24.6.2025) sprachen ihn frei. Das Bundesgericht hiess die Beschwerde des Verletzten gut und wies den Fall zurück – Ausgang offen.","Ordonnance pénale contre le contremaître; acquitté par le Tribunal de district de Zurzach et la Cour suprême argovienne (24.6.2025). Le TF a admis le recours de la victime et renvoyé l’affaire – issue ouverte.","Decreto d’accusa contro il capocantiere; assolto dal Tribunale distrettuale di Zurzach e dal Tribunale superiore argoviese (24.6.2025). Il TF ha accolto il ricorso della vittima e rinviato il caso – esito aperto.","Penalty order against the site foreman; acquitted by Zurzach District Court and the Aargau High Court (24.6.2025). The Federal Court upheld the injured worker's appeal and sent the case back – outcome open."),
 L("Baufirma; Unternehmen nicht angeklagt.","Entreprise de construction; entreprise non prévenue.","Impresa edile; azienda non imputata.","Construction firm; company not charged."),
 [D(L("Polier","Contremaître","Capocantiere","Site foreman"),FKV,"open",
   L("Zweimal freigesprochen; das Bundesgericht hob den Freispruch auf. Zum Unfallzeitpunkt waren weder Laufstege noch Auffangnetze montiert.","Acquitté deux fois; le TF a annulé l’acquittement. Au moment de l’accident, il n’y avait ni passerelles ni filets.","Assolto due volte; il TF ha annullato l’assoluzione. Al momento dell’incidente non c’erano né passerelle né reti.","Acquitted twice; the Federal Court quashed the acquittal. At the time there were no crawling boards or safety nets."),
   S(other=L("Ursprünglicher Strafbefehl: 120 Tagessätze à CHF 220 bedingt + CHF 5280 Busse","Ordonnance initiale: 120 jours-amende à CHF 220 avec sursis + CHF 5280 d’amende","Decreto iniziale: 120 aliquote da CHF 220 sospese + multa CHF 5280","Original penalty order: 120 day-fines of CHF 220 suspended + CHF 5,280 fine")))],
 ES("https://entscheidsuche.ch/docs/CH_BGer/CH_BGer_006_6B-784-2025_2026-08-19.html","de"),
 L("Sturz durch Dachplatte: Bundesgericht kippt Freispruch für Polier","Chute à travers une plaque de toit: le TF annule l’acquittement du contremaître","Caduta attraverso una lastra: il TF annulla l’assoluzione del capocantiere","Fall through roof panel: Federal Court overturns foreman's acquittal"),
 L("Auf dem Dach eines Neubaus brach ein Arbeiter durch eine nicht tragfähige Dachplatte und stürzte rund 2,5 m ab. Laufstege und Auffangnetze fehlten.","Sur le toit d’une construction neuve, un ouvrier a traversé une plaque non porteuse et chuté d’environ 2,5 m. Il n’y avait ni passerelles ni filets.","Sul tetto di una nuova costruzione un operaio ha sfondato una lastra non portante ed è caduto per circa 2,5 m. Mancavano passerelle e reti.","On the roof of a new building a worker broke through a non-load-bearing roof panel and fell about 2.5 m. There were no crawling boards or nets."),
 L("Schädel-Hirn-Trauma, Wirbel- und Rippenbrüche","Traumatisme crânien, fractures vertébrales et costales","Trauma cranico, fratture vertebrali e costali","Head injury, spinal and rib fractures"),
 L("Das Bundesgericht hiess die Beschwerde des Verletzten gut (Rüge zum Anklagegrundsatz) und wies den Fall zurück; das Obergericht muss neu urteilen.","Le TF a admis le recours de la victime (grief relatif au principe d’accusation) et renvoyé l’affaire; la Cour suprême doit rejuger.","Il TF ha accolto il ricorso della vittima (censura sul principio accusatorio) e rinviato il caso; il Tribunale superiore deve rigiudicare.","The Federal Court upheld the injured worker's appeal (on the indictment principle) and sent it back; the High Court must rule again."),
 L("Auch 2,5 m können schwer verletzen: nicht tragfähige Dachflächen nur mit Laufstegen oder Netzen.","Même 2,5 m peuvent blesser gravement: surfaces non porteuses seulement avec passerelles ou filets.","Anche 2,5 m possono ferire gravemente: superfici non portanti solo con passerelle o reti.","Even 2.5 m can cause serious injury: non-load-bearing roofs only with crawling boards or nets.")))

